import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000005;
    static boolean[] mark = new boolean[MAX_SIZE];

    static long powerMod(long base, int exp) {
        long result = 1;
        long mod = 1000000007;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(powerMod(p, (int)(p - 1)));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(powerMod(p, (int)p));
            sc.close();
            return;
        }

        int cycleCount = 0;
        for (int i = 1; i < p; i++) {
            if (mark[i]) continue;
            long current = i;
            while (!mark[(int)current]) {
                mark[(int)current] = true;
                current = (current * k) % p;
            }
            cycleCount++;
        }
        System.out.println(powerMod(p, cycleCount));
        sc.close();
    }
}
